"""Catálogo de divisiones y diccionarios de clasificación NBC→División, CINE→División, keywords."""

# ══════════════════════════════════════════════════════════════════════════════
# DIVISIONES UNINORTE: catálogo oficial (fuente única de verdad del pipeline)
# Todo valor de división usado en este archivo
# retroalimentacion.json se valida contra este catálogo antes de ejecutar.
# ══════════════════════════════════════════════════════════════════════════════
DIVISIONES = [
    "CIENCIAS BASICAS",
    "CIENCIAS DE LA SALUD",
    "DERECHO, CIENCIA POLITICA Y RELACIONES INTERNACIONALES",
    "ESCUELA DE ARQUITECTURA, URBANISMO Y DISEÑO",
    "ESCUELA DE NEGOCIOS",
    "HUMANIDADES, ARTES Y CIENCIAS SOCIALES",
    "INGENIERIAS",
    "INSTITUTO DE EDUCACION",
    "INSTITUTO DE IDIOMAS",
]

# "OTRO": programas sin división UniNorte correspondiente
DIVISIONES_VALIDAS = DIVISIONES + ["OTRO"]

# ══════════════════════════════════════════════════════════════════════════════
# NBC EXCLUSIVOS: mapeo directo a 1 sola división
# ══════════════════════════════════════════════════════════════════════════════
NBC_EXCLUSIVO = {
    "ANTROPOLOGIA Y ARTES LIBERALES": "HUMANIDADES, ARTES Y CIENCIAS SOCIALES",
    # ARQUITECTURA Y AFINES → movido a NBC_AMBIGUO (gerencia de la construcción → INGENIERIAS, como ProgramasUN)
    # COMUNICACION SOCIAL → movido a NBC_AMBIGUO (ver regla para comunicacion politica)
    # CONTADURIA PUBLICA → movido a NBC_AMBIGUO (auditoría en salud → SALUD, auditoría de sistemas → INGENIERIAS)
    # DISEÑO (y su variante DISENIO) → movido a NBC_AMBIGUO (mercadeo y negocios de moda → NEGOCIOS; audiovisual → HUMANIDADES
    # ingeniería, informática y producción industrial de vestuario → INGENIERIAS)
    "ENFERMERIA": "CIENCIAS DE LA SALUD",
    # FILOSOFIA, TEOLOGIA Y AFINES → movido a NBC_AMBIGUO (teología y formación confesional → HUMANIDADES, su default)
    # FISICA → movido a NBC_AMBIGUO (ingeniería física, instrumentación, metrología y materiales → INGENIERIAS)
    # GEOGRAFIA, HISTORIA → movido a NBC_AMBIGUO (derecho → DERECHO; archivística → HUMANIDADES; riesgo y ambiente → INGENIERIAS; teoría del arte y la arquitectura → ARQUITECTURA)
    # INGENIERIA ADMINISTRATIVA Y AFINES → movido a NBC_AMBIGUO (logística, finanzas y mercadeo → NEGOCIOS; agronegocios → NEGOCIOS)
    "INGENIERIA BIOMEDICA Y AFINES": "INGENIERIAS",
    "INGENIERIA DE MINAS, METALURGIA Y AFINES": "INGENIERIAS",
    "INGENIERIA ELECTRICA Y AFINES": "INGENIERIAS",
    # MATEMATICAS, ESTADISTICA Y AFINES → movido a NBC_AMBIGUO (enseñanza → EDUCACION; analítica, bases de datos e IA → INGENIERIAS)
    "MUSICA": "HUMANIDADES, ARTES Y CIENCIAS SOCIALES",
    "NUTRICION Y DIETETICA": "CIENCIAS DE LA SALUD",
    "ODONTOLOGIA": "CIENCIAS DE LA SALUD",
    # QUIMICA Y AFINES → movido a NBC_AMBIGUO (regencia y farmacia clínica → SALUD; ingeniería, calidad y materiales → INGENIERIAS)
    # SALUD PUBLICA → movido a NBC_AMBIGUO (salud mental psicosocial → HUMANIDADES)
    # TERAPIAS → movido a NBC_AMBIGUO (primera infancia → EDUCACION; psicología y discapacidad e inclusión social → HUMANIDADES)
    # ARTES REPRESENTATIVAS → movido a NBC_AMBIGUO (licenciaturas en educación → EDUCACION; ilustración y lo gráfico → ARQUITECTURA)
    # --- NBC adicionales ---
    # BACTERIOLOGIA → movido a NBC_AMBIGUO (bioquímica y microbiología no clínica → CIENCIAS BASICAS)
    # Antes NBC_AMBIGUO sin reglas (siempre su default)
    # OPTOMETRIA, OTROS PROGRAMAS DE CIENCIAS DE LA SALUD → movido a NBC_AMBIGUO (salud mental psicosocial → HUMANIDADES)
    # INGENIERIA AGRONOMICA, PECUARIA Y AFINES, MEDICINA VETERINARIA y ZOOTECNIA → movidos a NBC_AMBIGUO
    # (default OTRO + REGLAS_AGRO: las ingenierías, la gestión y la salud pública veterinaria salen de OTRO)
    # CIENCIA POLITICA, RELACIONES INTERNACIONALES → movido a NBC_AMBIGUO (negocios → NEGOCIOS; estudios latinoamericanos
    # europeos y del Caribe no políticos → HUMANIDADES)
    "INSTRUMENTACION QUIRURGICA": "CIENCIAS DE LA SALUD",
}

# ══════════════════════════════════════════════════════════════════════════════
# NBC AMBIGUOS: divisiones posibles con default y reglas de desempate
# Cada entrada: {"default": str | None, "reglas": list[tuple]}
# Las reglas son (campo, patron, division): si campo contiene patron → division
# campo debe ser uno de CAMPOS_REGLA_NBC (se valida antes de ejecutar)
# Orden: en cada bloque gana la PRIMERA regla cuyo patrón aparece en el campo (subcadena, sin límites de palabra)
#   así que las específicas van antes que las generales ('gerencia de proyectos sociales' antes de
#   'gerencia de proyecto'). No reordenar: el validador detiene el pipeline si una regla queda tapada por otra
#   anterior que la contiene, pero no detecta dos patrones distintos que coinciden en el mismo nombre.
# ══════════════════════════════════════════════════════════════════════════════
CAMPOS_REGLA_NBC = ("nombre", "cine_detallado")

