# ══════════════════════════════════════════════════════════════════════════════
# OVERRIDES MANUALES: reclasificación forzada (se aplica al final: confianza ALTA, sin revisión)
# Clave: nombre del programa (texto). Corrige todo programa con ese nombre exacto, sin importar su
#   SNIES, en todos los archivos. Se compara sin distinguir mayúsculas, tildes ni puntuación
#   (formato normalizar_para_keywords). Un nombre con caracteres dañados ('¿', '�') o truncado por la fuente
#   toma el override de su nombre limpio o completo: no hace falta agregar la variante, salvo que deba tener otra
#   división o que su nombre limpio coincida con overrides de divisiones distintas. Las erratas sin esos caracteres
#   ("especializacin") sí son nombres distintos y van como entradas aparte.
# Los nombres también son referencia de la Capa 2: un programa nuevo con nombre parecido vota esa división.
# Orden: no reordenar ni ordenar alfabéticamente. Con igual parecido en la Capa 2 gana la referencia que aparece
#   primero (medido: invertir el orden cambia la división de 14 de 1.211 programas nuevos). Las entradas
#   nuevas se agregan sin mover las existentes.
# Solo nombres: la división de un SNIES concreto la fijan ProgramasUN.xlsx (prevalece sobre estos
#   overrides) y retroalimentacion.json, que guarda automáticamente el resultado de cada override.
# Entradas agrupadas por tema ("# --- Tema → DIVISIÓN ---").
# Valores con formato display (se validan contra el catálogo antes de ejecutar).
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
