# 'innovacion y gestion de empresas'. Solo adjetivo ↔ sustantivo y singular ↔ plural del mismo término .
# Formato: forma → término base (normalizado, sin tildes). Se valida antes de ejecutar.
# ══════════════════════════════════════════════════════════════════════════════
